  schema={'@context':'https://schema.org','@type':'Article','headline':d['title'],'description':d['desc'],'datePublished':'2026-09-03','dateModified':'2026-09-03','inLanguage':lang,'author':{'@type':'Organization','name':'Northia Marketing Consultancy Ltd.'},'mainEntityOfPage':f'https://northiamarketing.com/{base}{sfx}.html','audience':{'@type':'Audience','audienceType':d['facts'][0]}}
  tabs=f'<div class="language-tabs"><a class="{"on" if loc=="en" else ""}" href="{base}.html">EN</a><a class="{"on" if loc=="tc" else ""}" href="{base}-zh-hk.html">繁中</a><a class="{"on" if loc=="sc" else ""}" href="{base}-zh-cn.html">简中</a></div>'
  facthtml=''.join(f'<div><strong>{escape(k)}</strong><span>{escape(v)}</span></div>' for k,v in zip(facts,d['facts']))
  cta='Request a free audit' if loc=='en' else ('申請免費品牌診斷' if loc=='tc' else '申请免费品牌诊断')
  html=f'''<!DOCTYPE html><html lang="{lang}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(d['title'])} | Northia</title><meta name="description" content="{escape(d['desc'])}"><link rel="canonical" href="https://northiamarketing.com/{base}{sfx}.html">{alts}<link rel="stylesheet" href="seo-pages.css"><link rel="alternate" type="text/markdown" href="/{base}{sfx}.md"><link rel="describedby" href="/llms.txt"><script type="application/ld+json">{json.dumps(schema,ensure_ascii=False)}</script></head><body><header class="header"><div class="wrap nav"><a class="brand" href="index.html"><img alt="" src="assets/northia-mark.png" width="38" height="38"><span>NORTHI<b>A</b></span></a><nav><a href="asia-to-world-marketing{sfx}.html">Asia to the World</a><a href="kol-influencer-marketing-asia{sfx}.html">KOL</a><a href="community-marketing-services{sfx}.html">Community</a></nav>{tabs}</div></header><main><article><section class="article-hero"><div class="wrap"><p class="eyebrow">2026 application guide</p><h1>{escape(d['title'])}</h1><p class="lead">{escape(d['desc'])}</p><div class="scenario-strip">{facthtml}</div></div></section><div class="wrap article-layout"><div class="article-body">{sec}{src}</div><aside class="article-aside"><h3>Northia</h3><a class="btn dark" href="index.html#contact">{cta}</a></aside></div></article></main><footer class="footer"><div class="wrap"><div class="copy">© 2026 Northia Marketing Consultancy Ltd.</div></div></footer></body></html>'''
